#define MAX_DIST 100.
#define SURF_DIST .001
#define EPS .0001
#define PI 3.14
#define PI2 6.28
#define saturate(a) clamp(a,0.,1.)
#define S(a,b,t) smoothstep(a,b,t)
#define TS(a,b,c,d,t) smoothstep(a,b,t) * smoothstep(d,c,t)
#define REP(p,r) mod(p,r) - r * .5  

/*
 * utilities
 */

// https://iquilezles.org/articles/palettes/
vec3 palette(float t)
{
    vec3 a = vec3(.1, .3, .8);
    vec3 b = vec3(.8, .4, .1);
    vec3 c = vec3(.4, .8, .9);
    vec3 d = vec3(.2, .9, .6);
    return a + b*cos( 6.283185*(c*t+d) );
}

float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

vec2 pmod(vec2 p, float s) {
    float a = PI / s - atan(p.x, p.y);
    float n = PI2 / s;
    a = floor(a / n) * n;
    p *= rot(-a);
    return p;
}

// ref: http://blog.hvidtfeldts.net/index.php/2011/08/distance-estimated-3d-fractals-iii-folding-space/
vec3 pmodn(vec3 p, vec3 n) {
    return p - 2. * min(0., dot(p, n)) * n;
}

float sdSphere(vec3 p, float s) {
    return length(p) - s;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.);
}

float sdRoundBox(vec3 p, vec3 b, float r) {
    vec3 q = abs(p) - b + r;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.) - r;
}

float sdCapsule( vec3 p, vec3 a, vec3 b, float r ) {
  vec3 pa = p - a, ba = b - a;
  float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
  return length( pa - ba*h ) - r;
}

float sdCylinder( vec3 p, vec3 c ) {
  return length(p.xz-c.xy)-c.z;
}


float opUnion(float d1, float d2) {
    return min(d1, d2);
}

vec2 opUnion2(vec2 a, vec2 b) {
	return a.x < b.x ? a : b;
}

vec3 opUnion3(vec3 a, vec3 b) {
	return a.x < b.x ? a : b;
}

// d2 から d1 を引く
float opSub(float d1, float d2) {
    return max(-d1, d2);
}

float opSmooth(float d1, float d2, float k) {
    float h = clamp(.5 + .5 *(d2 - d1) / k, 0., 1.);
    return mix(d2, d1, h) - k * h * (1. - h);
}

float opSmoothSub(float d1, float d2, float k) {
    float h = clamp(.5 - .5 * (d2 + d1) / k, 0., 1.);
    return mix(d2, -d1, h) + k * h * (1. - h);
}

float particle(vec3 p, float re, float t) {
    vec3 q = p;
    q.x += sin(q.z * .8 + t * 2.) * .4;
    q.y += sin(q.z * .8 + t * 2.) * .4;
    q.z += t * 7.5;
    // q.xy *= rot(t * .1);
    q = REP(q, re);

    return sdBox(q, vec3(.002, .002, 1.2));
}

/* end utilities */

vec2 scene(vec3 p) {
    float mat = 0.;
    float t = iTime;    
    vec2 res = vec2(10000., 0.);

    p.xy *= rot(sin(p.x + p.y) * .01 + p.z * .2 + t * .2);

    float sp = 2.7;

    vec3 q1 = p;
    vec3 _q = q1;

    q1.z += t * sp;
    q1.xz = REP(q1.xz, 2.);

    res = opUnion2(
        res,
        vec2(
            sdCylinder(q1, vec3(0., 0., .1)),
            1.
        )
    );

    vec3 q2 = p;
    q2.y -= t * 2.5;
    q2.z += t * sp;
    vec2 id2 = floor(q2.xy * vec2(2., 4.));
    float hash = rand(id2);
    q2 = REP(q2, vec3(2., 4., 2.));
    q2.y -= id2.x * .05;
    q2.xz *= rot(q2.y + t * 3.);

    res = opUnion2(
        res,
        vec2(
            sdBox(q2, vec3(.12, -.1 + hash * 2., .01)),
            2.
        )
    );
    res = opUnion2(
        res,
        vec2(
            sdBox(q2, vec3(.01, -1. + hash * 4., .12)),
            3.
        )
    );

    vec3 q3 = p;
    q3.z += t * sp;
    q3.xy *= rot(3.14 * .5);
    q3.xz = REP(q3.xz, 2.);
    res = opUnion2(
        res,
        vec2(
            sdCylinder(q3, vec3(0., 0., .05)),
            4.
        )
    );

    res = opUnion2(res, vec2(particle(p, 3.5, t), 2.));
    res = opUnion2(res, vec2(particle(p + vec3(.5, .5, 3.), 4., t), 3.));

    return res;
}

vec3 getNormal(vec3 p) {
	vec2 e = vec2(1., -1.) * EPS;
    return normalize(
        e.xyy * scene(p + e.xyy).x+
        e.yxy * scene(p + e.yxy).x+
        e.yyx * scene(p + e.yyx).x+
        e.xxx * scene(p + e.xxx).x
    );
}

vec2 raymarch(vec3 ro, vec3 rd, float side, inout vec3 emissive) {
    float accDist = 0.;    
    float mat = 0.;

    for(int i = 0; i < 99; i++) {
        vec3 p = ro + rd * accDist;
        vec2 result = scene(p);
        float dist = result.x * side;
        mat = result.y;
        if(abs(dist) < SURF_DIST || accDist > MAX_DIST) {
            break;
        }
        dist *= .5; // opt
        accDist += dist;      

        if(mat < 1.5) {
        } else if(mat < 2.5) {            
            emissive += .02 / abs(dist) * vec3(1., .02, .01);
        } else if(mat < 3.5) {            
            emissive += .01 / abs(dist) * vec3(.02, 1., 1.);
        } else if(mat < 4.5) {            
            //
        } else if(mat < 5.5) {            
            emissive += .01 / abs(dist) * vec3(.02, 1., 1.);
        }        
    }

    return vec2(accDist, mat);
}


vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 forward = normalize(l - p);
    vec3 right = normalize(cross(vec3(0., 1., 0.), forward));
    vec3 up = normalize(cross(forward, right));

    return normalize(right * uv.x + up * uv.y + forward * z);        
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime;

    vec2 uv = (fragCoord.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);

    uv *= rot(t * .02);

    vec2 m = (iMouse.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);
    vec3 ro = vec3(
       0.,
        0.,
        -10.
    );
    vec3 tao = vec3(1., 1., 1.);
    tao.xz *= rot(t * .1);    
    tao.yz *= rot(-t * .01);
    vec3 ta = ro + tao;

    vec3 rd = getRayDir(uv, ro, ta, 1.35);

    vec3 emissive = vec3(0.);

    vec2 result = raymarch(ro, rd, 1., emissive);
    float dist = result.x;
    float mat = result.y;

    vec3 col = vec3(0.);
    vec3 emissiveColor = vec3(0.);

    if(dist < MAX_DIST) {    
        vec3 p = ro + rd * dist;
        vec3 l = normalize(vec3(1., 1., -1.));
        vec3 n = getNormal(p);    
        vec3 r = reflect(rd, n);

        float diffuse = dot(l, n) * .5 + .5;

        vec3 diffuseColor = vec3(0.);

        if(mat < 1.5) {
            diffuseColor = vec3(0., 0., 0.);
        } else if(mat < 2.5) {
            diffuseColor = vec3(0., 1., 1.);        
        }

        col = vec3(diffuse) * diffuseColor;
    }

    col += emissive;

    col *= pow(exp(-dist * .35), 1.3);

    col = pow(col, vec3(.4545));

    col *= smoothstep(2., 1., length(uv));

    fragColor = vec4(col, 1.);
}
